package com.ensam.inventia.dto.response; import java.time.LocalDateTime; public record ApiResponse<T>(boolean success, T data, String message, String error, Integer status, LocalDateTime timestamp) { public static <T> ApiResponse<T> ok(T data,String message){return new ApiResponse<>(true,data,message,null,null,null);} public static <T> ApiResponse<T> fail(String error,int status){return new ApiResponse<>(false,null,null,error,status,LocalDateTime.now());} }